(() => {
'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n).toLocaleString('vi-VN')+' đ';
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem('bee.'+k))??f}catch{return f}};
const write=(k,v)=>{try{localStorage.setItem('bee.'+k,JSON.stringify(v))}catch{toast('Trình duyệt không cho lưu dữ liệu.')}};
let products=read('products',BEE_DATA.products),cart=read('cart',[]),user=read('user',null),orders=read('orders',[]),categories=read('categories',BEE_DATA.categories),homeCategory='Sản phẩm hot',selected={size:'',color:'',qty:1};
// Refresh the placeholder catalog once when real product photos are supplied.
// Keep a recoverable copy of previous demo data and keep user-added products.
if (read('catalogVersion', null) !== BEE_DATA.version) {
  write('catalogBeforePhotos', {products, categories, cart});
  const custom = products.filter(p => p.id > 12);
  products = [...BEE_DATA.products, ...custom];
  categories = [...new Set([...BEE_DATA.categories, ...custom.map(p=>p.category)])];
  cart = cart.filter(c => products.some(p=>p.id===c.id && p.colors.includes(c.color) && p.sizes.includes(c.size)));
  write('products', products); write('categories', categories); write('cart', cart);
  if(user) write('cart.'+user.email,cart);
  write('catalogVersion', BEE_DATA.version);
}
// Refresh photos while keeping edited product details.
if (read('photoVersion', null) !== BEE_DATA.photoVersion) {
  products.forEach(p => {
    const source = BEE_DATA.products.find(item => item.id === p.id);
    if(source) p.image = source.image;
  });
  write('products', products);
  write('photoVersion', BEE_DATA.photoVersion);
}
let promotions=read('promotions',[{id:1,name:'Bee Sale mẫu',percent:15,ids:[1,5],start:'2026-01-01',end:'2027-12-31',active:true}]),reviews=read('reviews',[]);
function prepareProduct(p){
  if(!p.sku)p.sku='BEE'+String(p.id).padStart(3,'0');
  if(!Array.isArray(p.sizes)||!p.sizes.length)p.sizes=['Freesize'];
  if(!Array.isArray(p.colors)||!p.colors.length)p.colors=['Mặc định'];
}
products.forEach(p=>{if((BEE_DATA.removedImages||[]).includes(p.image))delete p.image;prepareProduct(p)});
function available(p,size,color){return p&&p.active!==false&&p.sizes.includes(size)&&p.colors.includes(color)?99:0}
const orderTotal=o=>o.items.reduce((sum,item)=>sum+Number(item.price)*Number(item.qty),0);
orders.forEach(o=>{if(o.status==='Đang giao')o.status='Đang xử lý'});
function discount(p){const today=new Date().toLocaleDateString('en-CA');return Math.max(0,...promotions.filter(x=>x.active&&x.start<=today&&x.end>=today&&x.ids.includes(p.id)).map(x=>x.percent))}
function finalPrice(p){return p?Math.round(p.price*(100-discount(p))/100):0}
function priceLabel(p){const sale=finalPrice(p)<p.price;return `${sale?'<del class="old-price">'+money(p.price)+'</del> ':''}${money(finalPrice(p))}`}
function isWish(id){return user&&read('wish.'+user.email,[]).includes(id)}
const colors={'Trắng':'#f4f2ec','Kem':'#d7cbb2','Đen':'#30322e','Cam':'#ed652d','Xanh':'#6f8890'};
const icons={bag:'M5 6h14l1 15H4L5 6Z M8 7V5a4 4 0 0 1 8 0v2',user:'M20 21v-2a7 7 0 0 0-14 0v2 M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',search:'m21 21-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',arrow:'M4 12h16 m-6-6 6 6-6 6',box:'m3 7 9-5 9 5v10l-9 5-9-5V7Z m0 0 9 5 9-5 M12 12v10',truck:'M1 4h13v13H1V4Z M14 9h5l4 5v3h-9 M7 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z M21 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',check:'m4 12 5 5L20 6',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',menu:'M3 6h18 M3 12h18 M3 18h18'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.box}" stroke-linejoin="round" stroke-linecap="round"/></svg>`;
const link=(route,label,cls='')=>`<a href="#/${route}" class="${cls}">${label}</a>`;
const brand = () => {
  const asset = document.querySelector('#bee-brand-asset');
  const source = asset ? JSON.parse(asset.textContent) : 'assets/images/logo-bee-store.png';
  return `<a href="#/" class="brand brand-logo" aria-label="Bee Store — về trang chủ"><img src="${source}" alt="Logo Bee Store" width="1536" height="1024"></a>`;
};
const product=id=>products.find(p=>p.id===Number(id));
const total=()=>cart.reduce((n,c)=>n+finalPrice(product(c.id))*c.qty,0);
let productImageAssets;
function art(p,color){if(p.image && !(BEE_DATA.removedImages||[]).includes(p.image)){if(productImageAssets===undefined){const embedded=document.querySelector('#bee-product-assets');productImageAssets=embedded?JSON.parse(embedded.textContent):{};}return `<img src="${esc(productImageAssets[p.image]||p.image)}" alt="${esc(p.name)}" width="1400" height="1400">`}const fill=colors[color||p.color]||'#dbcfb7';let shape='';
if(p.art==='pants')shape=`<path d="M110 60h140l18 266-78 3-10-164-12 164-80-3Z" fill="${fill}"/><path d="M110 78h140M180 60v105m-66-73q5 44 36 45m96-45q-5 44-36 45" fill="none" stroke="#0002" stroke-width="3"/><path d="M94 300h73m25 0h72" stroke="#0002" stroke-width="3"/>`;
else{shape=`<path d="m126 73-66 39 28 66 33-17-8 158h134l-8-158 33 17 28-66-66-39q-52 20-108 0Z" fill="${fill}"/><path d="M151 74q29 43 58 0" fill="none" stroke="#0003" stroke-width="9"/><path d="m121 161 6-60m112 60-6-60M115 301h130" stroke="#0002" fill="none" stroke-width="3"/>`;
if(p.art==='shirt')shape+=`<path d="m151 75 29 24-22 21-20-38m71-7-29 24 22 21 20-38M180 99v219" fill="none" stroke="#0003" stroke-width="3"/><path d="M204 135h24v29h-24z" fill="#0001"/>${[130,165,200,235,270].map(y=>`<circle cx="185" cy="${y}" r="2" fill="#0005"/>`).join('')}`;
else if(p.art==='jacket')shape+=`<path d="M180 96v223" stroke="#e6e1d0" stroke-width="7"/><path d="m131 238 26 23m72-23-26 23" stroke="#0003" stroke-width="3"/><text x="203" y="150" fill="#ece8d9" font-size="26" font-family="Arial" font-weight="900">B</text>`;
else shape+=`<text x="180" y="172" text-anchor="middle" font-family="Arial" font-weight="900" font-size="26" letter-spacing="-1" fill="${p.color==='Đen'?'#e9e0ce':'#30382f'}">BEE.</text><text x="180" y="189" text-anchor="middle" font-family="Arial" font-size="6" letter-spacing="2" fill="#30382f">YOUR EVERYDAY CLUB</text>`;}
return `<svg viewBox="0 0 360 380" role="img" aria-label="Minh họa ${esc(p.category)} — chờ ảnh sản phẩm"><ellipse cx="180" cy="341" rx="89" ry="10" fill="#00000009"/>${shape}</svg>`;}
function card(p) {
  const sale = finalPrice(p) < p.price;
  const badge = sale ? `SALE −${discount(p)}%` : (p.tag || '');
  return `<article class="product-card">
    <a class="product-visual" href="#/product/${p.id}" style="--tile:${p.bg}">${art(p)}</a>
    <div class="product-meta">
      <div class="product-title"><h3>${link('product/'+p.id,esc(p.name))}</h3><p>${esc(p.category)} · Bee Store</p></div>
      <div class="card-price-row">
        <div class="card-price-content">
          <div class="card-price-reference">${sale ? `<del class="old-price">${money(p.price)}</del>` : ''}${badge ? `<span class="product-tag ${sale ? 'sale-tag' : ''}">${esc(badge)}</span>` : ''}</div>
          <div class="price">${money(finalPrice(p))}</div>
          ${p.priceNote ? `<small class="price-note">${esc(p.priceNote)}</small>` : ''}
        </div>
        <button class="wish-button" type="button" data-action="wish" data-id="${p.id}" aria-label="${isWish(p.id)?'Bỏ yêu thích':'Yêu thích'} ${esc(p.name)}" aria-pressed="${!!isWish(p.id)}"><svg class="wish-heart" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M12 20.5 3.7 12.6C-1.6 7.5 5.8-.3 12 6.1 18.2-.3 25.6 7.5 20.3 12.6Z"/></svg></button>
      </div>
    </div>
  </article>`;
}
function header(){return `<div class="announcement">BEE STORE CAMPUS COLLECTION &nbsp; / &nbsp; MẶC THEO CÁCH CỦA BẠN</div><header class="header"><div class="wrap nav">${brand()}<nav class="navlinks" aria-label="Điều hướng chính">${link('','Trang chủ')}${link('products','Sản phẩm')}${link('sale','Sale')}${link('wishlist','Yêu thích')}</nav><div class="navtools">${link('products',icon('search'), 'icon-link')}${link(user?'account':'login',icon('user')+`<span class="account-label">${user?esc(user.name.split(' ').pop()):'Tài khoản'}</span>`,'icon-link')}${link('cart',icon('bag')+`<span class="bagcount">${cart.reduce((n,c)=>n+c.qty,0)}</span>`,'icon-link')}<button class="mobile-menu" aria-label="Mở menu" data-action="menu">${icon('menu')}</button></div></div></header>`;}
function footer(){return `<div class="wrap perks"><div class="perk">${icon('box')}<div><b>Chọn chất riêng của bạn</b><p>Những thiết kế dễ mặc, dễ phối mỗi ngày.</p></div></div><div class="perk">${icon('bag')}<div><b>Mua sắm tại Bee Store</b><p>Cửa hàng trực tiếp tiếp nhận và xử lý đơn hàng.</p></div></div><div class="perk">${icon('check')}<div><b>Thanh toán khi nhận hàng</b><p>Đặt hàng thuận tiện với phương thức COD.</p></div></div></div><footer class="footer"><div class="wrap"><div class="footer-grid"><div>${brand()}<p>Thời trang sinh viên. Tinh thần tự do.<br>Để mỗi ngày đến trường đều là chính bạn.</p></div><div><h4>KHÁM PHÁ</h4>${link('products','Tất cả sản phẩm')}${link('sale','Hàng khuyến mãi')}${link('wishlist','Sản phẩm yêu thích')}${link('orders','Đơn hàng của bạn')}</div><div><h4>BEE STORE</h4>${link('account','Tài khoản')}${link('cart','Giỏ hàng')}${link('admin','Xem giao diện quản trị ↗')}</div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Bee Store. Đồ án website thời trang.</span><span>Made for campus. Made for you.</span></div></div></footer>`;}
function crumb(t){return `<div class="wrap breadcrumb">${link('','Trang chủ')} &nbsp; / &nbsp; ${esc(t)}</div>`;}
function empty(title,text,route='products',label='Khám phá sản phẩm'){return `<div class="empty"><h2>${title}</h2><p>${text}</p>${link(route,label+' &nbsp; ↗','btn')}</div>`;}

// Home banner: retain the original 3:2 image ratio and loop 1 → 2 → 3 → 4 → 1.
let heroTimer = null;
function stopHeroCarousel() {
  if (heroTimer !== null) clearTimeout(heroTimer);
  heroTimer = null;
}
function heroCarousel() {
  const embedded = document.querySelector('#bee-banner-assets');
  const sources = embedded ? JSON.parse(embedded.textContent) : [];
  const descriptions = [
    'Bee Store — áo hoodie, nón và túi tote',
    'Bee Store — áo thun, nón và móc khóa',
    'Bee Store — áo dài tay, nón len và túi tote',
    'Bee Store — áo sweatshirt, nón và huy hiệu'
  ];
  return `<div class="hero-art hero-carousel" role="region" aria-roledescription="băng chuyền" aria-label="Bộ ảnh Bee Store" tabindex="0">
    <div class="hero-slides">${descriptions.map((description, i) => `<div class="hero-slide ${i === 0 ? 'is-active' : ''}" role="group" aria-roledescription="ảnh" aria-label="${i+1} / 4" aria-hidden="${i !== 0}"><img src="${sources[i] || `assets/images/panner_${i+1}.png`}" alt="${description}" width="1536" height="1024" decoding="async" ${i===0?'fetchpriority="high"':''}></div>`).join('')}</div>
    <div class="hero-carousel-controls"><div class="hero-dots">${descriptions.map((_,i)=>`<button type="button" class="hero-dot ${i===0?'is-active':''}" aria-label="Xem ảnh ${i+1}" aria-pressed="${i===0}"></button>`).join('')}</div></div>
  </div>`;
}
function initHeroCarousel() {
  const root = document.querySelector('.hero-carousel');
  if (!root?.querySelectorAll) return; // The static HTML builder has no DOM events.
  const slides = [...root.querySelectorAll('.hero-slide')];
  const dots = [...root.querySelectorAll('.hero-dot')];
  let current = 0;
  function schedule() {
    stopHeroCarousel();
    if (!document.hidden) {
      heroTimer = setTimeout(() => { show(current + 1); }, 1500);
    }
  }
  function show(next) {
    current = (next + slides.length) % slides.length;
    slides.forEach((slide,i) => {
      slide.classList.toggle('is-active',i===current);
      slide.setAttribute('aria-hidden',String(i!==current));
      dots[i].classList.toggle('is-active',i===current);
      dots[i].setAttribute('aria-pressed',String(i===current));
    });
    schedule();
  }
  dots.forEach((dot,i) => dot.addEventListener('click', () => show(i)));
  root.addEventListener('keydown', event => {
    if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
      event.preventDefault(); show(current + (event.key==='ArrowRight' ? 1 : -1));
    }
  });
  // Assigning the handler replaces the one from a previous home render.
  document.onvisibilitychange = () => { if (root.isConnected) schedule(); };
  schedule();
}

function homeProducts(){return products.filter(p=>p.active!==false&&(homeCategory==='Sản phẩm đang sale'?finalPrice(p)<p.price:p.hot===true)).slice(0,4)}
function home(){return `<main><div class="wrap"><section class="hero"><div><div class="eyebrow">The campus collection / 2026</div><h1>Mặc đơn giản.<br><em>Chất riêng</em><br>không giới hạn.</h1><p class="intro">Từ giảng đường đến những cuộc hẹn sau giờ học.<br>Khám phá tủ đồ mang tinh thần trẻ, tự do và đầy cá tính.</p><div class="hero-cta">${link('products','Khám phá ngay '+icon('arrow'),'btn')}${link('sale','Khám phá hàng Sale ↗','text-link')}</div></div>${heroCarousel()}</section><div class="ticker"><span>✳ THỜI TRANG SINH VIÊN</span><span>EVERYDAY COMFORT</span><span>✳ PHONG CÁCH BEE</span><span>WEAR YOUR OWN WAY</span></div><section class="section"><div class="section-top"><div><div class="eyebrow">Bee Store picks</div><h2>Lựa chọn dành cho bạn.</h2></div><div class="category-tabs">${['Sản phẩm hot','Sản phẩm đang sale'].map(c=>`<button class="chip ${c===homeCategory?'active':''}" data-action="home-category" data-value="${c}">${c}</button>`).join('')}</div></div><div class="product-grid">${homeProducts().map(card).join('') || '<p class="muted full-span">Hiện chưa có sản phẩm trong nhóm này.</p>'}</div><div style="text-align:center;margin-top:30px">${link('products','Xem tất cả sản phẩm '+icon('arrow'),'btn light')}</div></section><div class="gap"></div></div></main>`;}
function catalog(params){const q=params.get('q')||'',cat=params.get('category')||'',min=params.get('min')||'',max=params.get('max')||'',sort=params.get('sort')||'new';let list=products.filter(p=>p.active!==false&&(!params.get('sale')||finalPrice(p)<p.price)&&(!cat||p.category===cat)&&p.name.toLocaleLowerCase('vi').includes(q.toLocaleLowerCase('vi'))&&(!min||finalPrice(p)>=Number(min))&&(!max||finalPrice(p)<=Number(max)));list.sort((a,b)=>sort==='asc'?finalPrice(a)-finalPrice(b):sort==='desc'?finalPrice(b)-finalPrice(a):b.id-a.id);return `${crumb('Sản phẩm')}<main class="wrap"><div class="page-heading"><div class="eyebrow">Find your everyday favorites</div><h1>${params.get('sale')?'Ưu đãi cho tủ đồ mới.':'Tủ đồ của bạn.'}</h1><p>Những món đồ đơn giản. Những cách phối không giới hạn.</p></div><div class="catalog"><aside class="filters"><h3>Bộ lọc sản phẩm</h3><form id="filter-form">${params.get('sale')?'<input type="hidden" name="sale" value="1">':''}<div class="field"><label for="search">Tìm sản phẩm</label><input id="search" class="input" name="q" placeholder="Nhập tên sản phẩm…" value="${esc(q)}"></div><div class="field"><label>Danh mục</label><div class="radio-group">${['',...categories].map(c=>`<label><input type="radio" name="category" value="${esc(c)}" ${cat===c?'checked':''}>${c||'Tất cả sản phẩm'}</label>`).join('')}</div></div><div class="field"><label>Khoảng giá (đ)</label><div class="range"><input class="input" aria-label="Giá thấp nhất" type="number" min="0" name="min" placeholder="Từ" value="${esc(min)}"><input class="input" aria-label="Giá cao nhất" type="number" min="0" name="max" placeholder="Đến" value="${esc(max)}"></div></div><input type="hidden" name="sort" value="${esc(sort)}"><button class="btn full">Áp dụng bộ lọc</button><div style="margin-top:12px">${link('products','Xóa bộ lọc','text-link')}</div></form></aside><section><div class="catalog-toolbar"><p><b>${list.length}</b> sản phẩm ${cat?' / '+esc(cat):''}</p><select id="sort" aria-label="Sắp xếp">${[['new','Mới nhất'],['asc','Giá tăng dần'],['desc','Giá giảm dần']].map(([v,t])=>`<option value="${v}" ${v===sort?'selected':''}>${t}</option>`).join('')}</select></div>${list.length?`<div class="product-grid">${list.map(card).join('')}</div>`:empty('Chưa tìm thấy món đồ phù hợp','Thử thay đổi từ khóa hoặc xóa bộ lọc nhé.','products','Xóa bộ lọc')}</section></div></main>`;}
function detail(id){const p=product(id);if(!p||p.active===false)return `<main class="wrap section">${empty('Sản phẩm không khả dụng','Mời bạn khám phá những sản phẩm khác.')}</main>`;selected={size:p.sizes[0],color:p.colors[0],qty:1};return `${crumb(p.name)}<main class="wrap"><section class="detail"><div class="detail-art" id="detail-art" style="--tile:${p.bg}">${art(p,selected.color)}</div><div><div class="eyebrow">${esc(p.category)} / Campus essentials</div><h1>${esc(p.name)}</h1><p class="muted" style="font-size:11px">SKU: ${esc(p.sku)} &nbsp; · &nbsp; Bee Store collection</p><div class="detail-price">${priceLabel(p)}${p.priceNote?`<small class="price-note">${esc(p.priceNote)}</small>`:''}</div><div class="choice-group"><div class="choice-title">Màu sắc: <b id="color-label">${esc(selected.color)}</b></div>${p.colors.map((c,i)=>`<button class="choice color-choice ${!i?'active':''}" data-action="color" data-value="${esc(c)}" data-id="${p.id}">${esc(c)}</button>`).join('')}</div><div class="choice-group"><div class="choice-title">Kích thước</div>${p.sizes.map((s,i)=>`<button class="choice size-choice ${!i?'active':''}" data-action="size" data-value="${s}">${s}</button>`).join('')}</div><p class="stock" id="product-availability">${available(p,selected.size,selected.color)?'● Sản phẩm đang kinh doanh':'○ Lựa chọn không khả dụng'}</p><div class="buy-row"><div class="quantity"><button aria-label="Giảm số lượng" data-action="qty" data-value="-1">−</button><span id="detail-qty">1</span><button aria-label="Tăng số lượng" data-action="qty" data-value="1" data-id="${p.id}">+</button></div><button class="btn" data-action="add-cart" data-id="${p.id}" ${!available(p,selected.size,selected.color)?'disabled':''}>${icon('bag')} Thêm vào giỏ hàng</button></div><div class="notice">Bee Store trực tiếp tiếp nhận và xử lý đơn hàng.</div><details open class="details-text"><summary>Thông tin sản phẩm</summary>Phom dáng dễ mặc, phù hợp cho những ngày đến trường và đi chơi. Ảnh sản phẩm do Bee Store cung cấp. Thông tin chất liệu và bảng số đo sẽ được cập nhật theo từng mẫu; giá, size và số lượng hiện dùng để trải nghiệm giao diện.</details><details class="details-text"><summary>Gợi ý chọn kích thước</summary>Chọn size bạn thường mặc. Bảng số đo chi tiết sẽ được bổ sung theo từng sản phẩm.</details></div></section>${reviewPanel(p)}</main>`;}
function cartPage(){return `${crumb('Giỏ hàng')}<main class="wrap"><div class="page-heading"><div class="eyebrow">Your good picks</div><h1>Giỏ hàng của bạn.</h1><p>${cart.length} lựa chọn đang chờ bạn.</p></div>${!cart.length?empty('Giỏ hàng đang trống','Chọn một món đồ để bắt đầu phong cách của bạn.'):`<div class="two-col"><section class="panel">${cart.map((c,i)=>{const p=product(c.id);return `<div class="cart-row"><a href="#/product/${p.id}" class="mini-art" style="--tile:${p.bg}">${art(p,c.color)}</a><div><h3>${link('product/'+p.id,esc(p.name))}</h3><p>${esc(c.color)} / Size ${esc(c.size)}</p><div class="quantity"><button aria-label="Giảm số lượng ${esc(p.name)}" data-action="cart-qty" data-index="${i}" data-value="-1">−</button><span>${c.qty}</span><button aria-label="Tăng số lượng ${esc(p.name)}" data-action="cart-qty" data-index="${i}" data-value="1">+</button></div></div><div style="text-align:right"><div class="price">${money(finalPrice(p)*c.qty)}</div><button class="remove" data-action="remove" data-index="${i}">Xóa sản phẩm</button></div></div>`}).join('')}<div style="margin-top:20px">${link('products','← Tiếp tục chọn đồ','text-link')}</div></section>${summary(true)}</div>`}<div class="gap"></div></main>`;}
function summary(button=false){return `<aside class="panel"><h3>Tóm tắt đơn hàng</h3><div class="totals"><div><span>Tiền hàng</span><span>${money(total())}</span></div><div class="grand"><span>Tổng cộng</span><span>${money(total())}</span></div></div>${button?link('checkout','Tiến hành đặt hàng '+icon('arrow'),'btn full'):''}<p class="muted" style="font-size:10px;margin:15px 0 0">Thanh toán COD khi nhận hàng.</p></aside>`;}
const field=(name,label,type='text',value='',attrs='')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" class="input" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`;
function checkout(){if(!cart.length)return `<main class="wrap section">${empty('Giỏ hàng đang trống','Thêm sản phẩm trước khi đặt hàng.')}</main>`;if(!user)return auth('login','checkout');return `${crumb('Đặt hàng')}<main class="wrap"><div class="page-heading"><div class="eyebrow">One more step</div><h1>Gần đến tay bạn rồi.</h1><p>Điền thông tin để hoàn tất đơn hàng thử.</p></div><div class="two-col"><form id="checkout-form" class="panel"><h3>Thông tin nhận hàng</h3><div class="form-grid">${field('name','Họ và tên *','text',user.name,'required maxlength="100"')}${field('phone','Số điện thoại *','tel',user.phone||'','required pattern="[0-9]{10}" title="Nhập 10 chữ số"')}${field('city','Tỉnh / Thành phố *','text','','required')}${field('district','Quận / Huyện *','text','','required')}${field('ward','Phường / Xã *','text','','required')}${field('address','Số nhà, tên đường *','text',user.address||'','required')}</div><div class="field"><label for="note">Ghi chú</label><textarea id="note" name="note" rows="3" maxlength="500" placeholder="Lưu ý cho đơn hàng của bạn…"></textarea></div><div class="notice">Bản giao diện thử: đơn hàng được lưu trên trình duyệt, chưa gửi tới cửa hàng.</div><div class="gap"></div><button class="btn full">Xác nhận đặt hàng COD ${icon('arrow')}</button></form>${summary()}</div></main>`;}
function auth(mode,next='account'){let reg=mode==='register';return `${crumb(reg?'Đăng ký':'Đăng nhập')}<main class="wrap"><section class="auth"><div class="eyebrow">Welcome to the club</div><h1 style="margin:15px 0">${reg?'Gia nhập Bee Store.':'Chào bạn trở lại.'}</h1><p class="muted">${reg?'Tạo hồ sơ thử để trải nghiệm giao diện.':'Đăng nhập thử để khám phá luồng mua hàng.'}</p><form id="auth-form" data-mode="${mode}" data-next="${esc(next)}">${reg?field('name','Họ và tên *','text','','required maxlength="100"'):''}${field('email','Email *','email','','required maxlength="120"')}${reg?field('phone','Số điện thoại *','tel','','required pattern="[0-9]{10}" title="Nhập 10 chữ số"'):''}${field('password','Mật khẩu thử *','password','','required minlength="8" autocomplete="off"')}${reg?field('confirm','Nhập lại mật khẩu *','password','','required minlength="8"'):''}<p class="notice">Chế độ giao diện: chưa xác thực với máy chủ. Hãy dùng thông tin thử; mật khẩu không được lưu.</p><button class="btn full">${reg?'Tạo hồ sơ thử':'Vào tài khoản thử'} ${icon('arrow')}</button></form><p>${reg?'Đã có tài khoản?':'Bạn mới đến Bee Store?'} ${link(reg?'login':'register',reg?'Đăng nhập':'Đăng ký ngay','text-link')}</p></section></main>`;}
function account(){if(!user)return auth('login');return `${crumb('Tài khoản')}<main class="wrap"><div class="page-heading"><h1>Xin chào, ${esc(user.name)}.</h1><p>Không gian cá nhân của bạn tại Bee Store.</p></div><div class="two-col"><form id="account-form" class="panel"><h3>Thông tin cá nhân</h3>${field('name','Họ và tên','text',user.name,'required')}${field('email','Email','email',user.email,'disabled')}${field('phone','Số điện thoại','tel',user.phone||'','pattern="[0-9]{10}"')}${field('address','Địa chỉ mặc định','text',user.address||'')}<button class="btn">Lưu thông tin</button></form><aside class="panel"><h3>Tài khoản của bạn</h3><p><button class="text-link" data-action="password">Đổi mật khẩu</button></p><p>${link('orders','Xem đơn hàng →','text-link')}</p><button class="btn light full" data-action="logout">Đăng xuất</button><p class="muted" style="font-size:10px;margin-top:15px">Đây là hồ sơ thử được lưu trên thiết bị này.</p></aside></div></main>`;}
const statusClass=s=>s==='Hoàn thành'?'done':s==='Đã hủy'?'cancel':'';
const status=s=>`<span class="status ${statusClass(s)}">${esc(s)}</span>`;
function orderTable(list,admin=false){return `<div class="table-wrap"><table><thead><tr><th>Mã đơn / Ngày đặt</th><th>Khách hàng</th><th>Tổng tiền</th><th>Trạng thái</th><th></th></tr></thead><tbody>${list.length?list.map(o=>`<tr><td><b>${esc(o.id)}</b><small>${new Date(o.date).toLocaleDateString('vi-VN')}</small></td><td>${esc(o.name)}<small>${esc(o.phone)}</small></td><td>${money(orderTotal(o))}</td><td>${status(o.status)}${o.cancelRequest?'<small>Yêu cầu hủy đang chờ xử lý</small>':''}</td><td>${link((admin?'admin/order/':'order/')+o.id,'Chi tiết ↗','text-link')}</td></tr>`).join(''):'<tr><td colspan="5">Chưa có đơn hàng phù hợp.</td></tr>'}</tbody></table></div>`;}
function ordersPage(params){if(!user)return auth('login','orders');const st=params.get('status')||'';return `${crumb('Đơn hàng')}<main class="wrap section" style="padding-top:10px"><div class="page-heading"><h1>Đơn hàng của bạn.</h1><p>Theo dõi hành trình những món đồ đã chọn.</p></div><div class="chips" style="margin-bottom:25px">${['','Chờ xác nhận','Đã xác nhận','Đang xử lý','Hoàn thành','Đã hủy'].map(s=>link('orders'+(s?'?status='+encodeURIComponent(s):''),s||'Tất cả','chip '+(st===s?'active':''))).join('')}</div><div class="panel">${orderTable(orders.filter(o=>o.email===user.email&&(!st||o.status===st)))}</div></main>`;}
function orderDetail(id,admin=false){let o=orders.find(o=>o.id===id&&(admin||o.email===user?.email));if(!o)return `<main class="wrap section">${empty('Không tìm thấy đơn hàng','Đăng nhập đúng hồ sơ thử đã đặt hàng.','orders','Về danh sách đơn')}</main>`;return `${!admin?crumb('Chi tiết đơn'):''}<div class="${admin?'':'wrap section'}"><div class="admin-title"><div><h1>Đơn ${esc(o.id)}</h1><p>${new Date(o.date).toLocaleString('vi-VN')} · COD · Đơn thử</p></div>${status(o.status)}</div><div class="two-col"><section class="panel"><h3>Sản phẩm đã đặt</h3>${o.items.map(c=>`<div class="cart-row"><div class="mini-art" style="--tile:${c.bg}">${art(c,c.color)}</div><div><h3>${esc(c.name)}</h3><p>${esc(c.color)} / ${esc(c.size)} · Số lượng ${c.qty}</p></div><b class="price">${money(c.price*c.qty)}</b></div>`).join('')}<div class="totals"><div class="grand"><span>Tổng thanh toán</span><span>${money(orderTotal(o))}</span></div></div></section><aside class="panel"><h3>Thông tin nhận hàng</h3><p><b>${esc(o.name)}</b><br>${esc(o.phone)}</p><p class="muted">${esc(o.address)}</p>${o.note?`<p>Ghi chú: ${esc(o.note)}</p>`:''}${o.cancelRequest?`<p class="notice">Yêu cầu hủy: ${esc(o.cancelRequest)}</p>${admin?`<button class="btn full" data-action="approve-cancel" data-id="${o.id}">Chấp nhận hủy</button><button class="btn light full" data-action="reject-cancel" data-id="${o.id}">Từ chối yêu cầu</button>`:''}`:''}${o.cancelRejection?`<p class="notice">${esc(o.cancelRejection)}</p>`:''}${o.reason?`<p class="notice">Lý do hủy: ${esc(o.reason)}</p>`:''}${admin&&['Chờ xác nhận','Đã xác nhận','Đang xử lý'].includes(o.status)?`<button class="btn full" data-action="advance" data-id="${o.id}">${{'Chờ xác nhận':'Xác nhận đơn','Đã xác nhận':'Bắt đầu xử lý','Đang xử lý':'Hoàn thành đơn'}[o.status]}</button><div class="gap"></div>`:''}${(!o.cancelRequest&&(o.status==='Chờ xác nhận'||admin&&o.status==='Đã xác nhận'))?`<button class="btn light full" data-action="cancel" data-id="${o.id}">Hủy đơn hàng</button>`:''}</aside></div></div>`;}
function adminShell(path,params){const section=path[1]||'dashboard';const tabs=[['dashboard','Tổng quan','grid'],['products','Sản phẩm','bag'],['categories','Danh mục','box'],['orders','Đơn hàng','bag'],['customers','Tài khoản User','user'],['promotions','Khuyến mãi','box'],['reviews','Duyệt đánh giá','check']];return `<div class="admin-shell"><aside class="sidebar">${brand()}<div class="eyebrow" style="font-size:8px;margin-bottom:15px;color:#a8b09c">Workspace / Bee Store</div>${tabs.map(([r,t,i])=>link('admin/'+r,icon(i)+t,'item '+(section===r?'active':''))).join('')}<div class="side-bottom"><p>Giao diện quản trị thử<br>Dữ liệu lưu trên trình duyệt.</p>${link('','← Về cửa hàng')}</div></aside><main class="admin-main"><div class="admin-top"><span>Bee Store &nbsp; / &nbsp; Quản trị cửa hàng</span>${link('','Xem cửa hàng ↗','text-link')}</div>${section==='order'?orderDetail(path[2],true):(section==='dashboard'?statistics(params):adminPage(section,params))}</main></div>`;}
function adminPage(section,params){if(['promotions','reviews'].includes(section))return extraAdmin(section);if(section==='dashboard')return statistics(params);let q=params.get('q')||'',st=params.get('status')||'';if(section==='products'){const list=products.filter(p=>p.name.toLowerCase().includes(q.toLowerCase())&&(!st||(st==='active'?p.active!==false:p.active===false)));return `<div class="admin-title"><div><h1>Sản phẩm</h1><p>Quản lý tên, giá, hình ảnh, kích thước và màu sắc sản phẩm.</p></div><button class="btn" data-action="edit-product">+ Thêm sản phẩm</button></div><div class="panel"><form id="admin-filter" class="admin-table-tools"><input name="q" class="input" placeholder="Tìm tên sản phẩm…" value="${esc(q)}"><select name="status"><option value="">Tất cả trạng thái</option><option value="active" ${st==='active'?'selected':''}>Đang kinh doanh</option><option value="hidden" ${st==='hidden'?'selected':''}>Ngừng kinh doanh</option></select><button class="btn small">Tìm kiếm</button></form><div class="table-wrap"><table><thead><tr><th>Sản phẩm</th><th>Danh mục</th><th>Giá</th><th>Kích thước / Màu sắc</th><th>Trạng thái</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td><div class="admin-product"><div class="mini-art" style="--tile:${p.bg}">${art(p)}</div><div><b>${esc(p.name)}</b><small>${esc(p.sku)}</small></div></div></td><td>${esc(p.category)}</td><td>${money(finalPrice(p))}</td><td>${esc(p.sizes.join(', '))}<small>${esc(p.colors.join(', '))}</small></td><td>${status(p.active===false?'Ngừng kinh doanh':'Đang kinh doanh')}</td><td><button class="text-link" data-action="edit-product" data-id="${p.id}">Chỉnh sửa ↗</button></td></tr>`).join('')}</tbody></table></div></div>`;}
if(section==='categories')return `<div class="admin-title"><div><h1>Danh mục</h1><p>Sắp xếp các nhóm sản phẩm của cửa hàng.</p></div><button class="btn" data-action="category">+ Thêm danh mục</button></div><div class="panel table-wrap"><table><thead><tr><th>Danh mục</th><th>Số sản phẩm</th><th>Thao tác</th></tr></thead><tbody>${categories.map((c,i)=>`<tr><td><b>${esc(c)}</b></td><td>${products.filter(p=>p.category===c).length}</td><td><button class="text-link" data-action="category" data-index="${i}">Đổi tên</button></td></tr>`).join('')}</tbody></table></div>`;
if(section==='orders')return `<div class="admin-title"><div><h1>Đơn hàng</h1><p>Đơn thử được tạo từ quy trình mua hàng ở cửa hàng.</p></div></div><div class="panel"><form id="admin-filter" class="admin-table-tools"><input name="q" class="input" placeholder="Tìm mã đơn hoặc số điện thoại…" value="${esc(q)}"><select name="status"><option value="">Tất cả trạng thái</option>${['Chờ xác nhận','Đã xác nhận','Đang xử lý','Hoàn thành','Đã hủy'].map(s=>`<option ${s===st?'selected':''}>${s}</option>`).join('')}</select><button class="btn small">Lọc đơn</button></form>${orderTable(orders.filter(o=>(o.id.includes(q)||o.phone.includes(q))&&(!st||o.status===st)),true)}</div>`;
if(section==='customers'){let people=read('people',[]);return `<div class="admin-title"><div><h1>Khách hàng</h1><p>Danh sách hồ sơ thử đã tạo trên thiết bị này.</p></div></div><div class="panel table-wrap"><table><thead><tr><th>Họ tên</th><th>Email</th><th>Điện thoại</th><th>Trạng thái</th><th></th></tr></thead><tbody>${people.length?people.map((u,i)=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(u.phone)}</td><td>${status(u.locked?'Bị khóa':'Hoạt động')}</td><td><button class="text-link" data-action="lock" data-index="${i}">${u.locked?'Mở khóa':'Khóa tài khoản'}</button></td></tr>`).join(''):'<tr><td colspan="5">Chưa có hồ sơ thử. Tạo tại màn hình đăng ký.</td></tr>'}</tbody></table></div>`;}
return statistics(params);}

function modal(title,body){const d=$('#modal');d.innerHTML=`<div class="modal-top"><h2>${title}</h2><button class="close" data-action="close" aria-label="Đóng">×</button></div>${body}`;if(!d.open)d.showModal();}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
const route=()=>{const [p,q]=location.hash.replace(/^#\/?/,'').split('?');return {path:(p||'').split('/'),params:new URLSearchParams(q||'')}};
function go(r){if(location.hash==='#/'+r)render();else location.hash='/'+r;}
function render(){stopHeroCarousel();const {path,params}=route();const page=path[0];let body;document.title=(page==='admin'?'Quản trị':'Bee Store — Mặc chất riêng')+' | Bee Store';if(page==='admin')body=adminShell(path,params);else{body=page==='products'?catalog(params):page==='product'?detail(path[1]):page==='cart'?cartPage():page==='checkout'?checkout():page==='login'||page==='register'?auth(page):page==='account'?account():page==='orders'?ordersPage(params):page==='order'?orderDetail(path[1]):page==='sale'?salePage(params):page==='wishlist'?wishPage():page==='success'?`<main class="wrap section" style="max-width:650px;text-align:center"><div class="success-icon">✓</div><h1 style="font-size:38px">Đã nhận đơn hàng thử!</h1><p class="muted">Mã đơn ${esc(path[1])}. Bạn có thể kiểm tra và trải nghiệm xử lý đơn ở trang quản trị.</p><p class="notice">Đơn này chỉ phục vụ trải nghiệm giao diện, chưa gửi đến cửa hàng.</p>${link('order/'+path[1],'Xem chi tiết đơn ↗','btn')}</main>`:page===''?home():`<main class="wrap section">${empty('Trang không tồn tại','Quay lại cửa hàng để tiếp tục khám phá.','','Về trang chủ')}</main>`;body=header()+body+footer();}$('#app').innerHTML=body;initHeroCarousel();}
function saveCart(){write('cart',cart);if(user)write('cart.'+user.email,cart)}function saveProducts(){write('products',products)}function saveOrders(){write('orders',orders)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,p=product(b.dataset.id),i=Number(b.dataset.index);if(a==='menu')$('.navlinks').classList.toggle('open');if(a==='close')$('#modal').close();if(a==='home-category'){homeCategory=b.dataset.value;const y=scrollY;render();scrollTo(0,y)}if(a==='size'||a==='color'){selected[a]=b.dataset.value;$$('.'+a+'-choice').forEach(x=>x.classList.toggle('active',x===b));if(a==='color'){$('#color-label').textContent=selected.color;$('#detail-art').innerHTML=art(p,selected.color)}}if(a==='qty'){const n=selected.qty+Number(b.dataset.value);if(n<1||n>Math.min(available(product(route().path[1]),selected.size,selected.color),99))return toast('Mỗi lựa chọn được đặt từ 1 đến 99 sản phẩm.');selected.qty=n;$('#detail-qty').textContent=n}if(a==='add-cart'){if(!user){toast('Đăng nhập thử trước khi thêm giỏ nhé.');write('returnTo','product/'+p.id);go('login');return}if(p.active===false||available(p,selected.size,selected.color)<selected.qty)return toast('Sản phẩm hoặc lựa chọn không còn khả dụng.');const old=cart.find(c=>c.id===p.id&&c.size===selected.size&&c.color===selected.color);if((old?.qty||0)+selected.qty>Math.min(available(p,selected.size,selected.color),99))return toast('Mỗi lựa chọn được đặt tối đa 99 sản phẩm.');if(old)old.qty+=selected.qty;else cart.push({id:p.id,size:selected.size,color:selected.color,qty:selected.qty});saveCart();$('.bagcount').textContent=cart.reduce((s,c)=>s+c.qty,0);toast('Đã thêm vào giỏ hàng.')}if(a==='cart-qty'){const c=cart[i],n=c.qty+Number(b.dataset.value),p=product(c.id);if(n<1||n>Math.min(available(p,c.size,c.color),99))return toast('Mỗi lựa chọn được đặt từ 1 đến 99 sản phẩm.');c.qty=n;saveCart();render()}if(a==='remove'){cart.splice(i,1);saveCart();render();toast('Đã xóa sản phẩm khỏi giỏ.')}if(a==='logout'){saveCart();user=null;write('user',null);cart=[];saveCart();go('login');toast('Đã đăng xuất hồ sơ thử.')}if(a==='cancel'){modal('Hủy đơn hàng',`<form id="cancel-form" data-id="${esc(b.dataset.id)}"><div class="field"><label for="reason">Lý do hủy *</label><textarea id="reason" name="reason" maxlength="255" required rows="3"></textarea></div><p class="muted" style="font-size:11px">Cửa hàng ghi nhận lý do và cập nhật trạng thái đơn sau khi hủy.</p><button class="btn full">${route().path[0]==='admin'?'Xác nhận hủy đơn':'Gửi yêu cầu hủy'}</button></form>`)}if(a==='advance'){let o=orders.find(o=>o.id===b.dataset.id);let next={'Chờ xác nhận':'Đã xác nhận','Đã xác nhận':'Đang xử lý','Đang xử lý':'Hoàn thành'}[o?.status];if(o.cancelRequest)return toast('Hãy xử lý yêu cầu hủy trước khi chuyển trạng thái.');if(next){o.status=next;if(next==='Hoàn thành')o.completedAt=new Date().toISOString();saveOrders();render();toast('Đã cập nhật trạng thái đơn thử.')}}if(a==='edit-product'){modal(p?'Chỉnh sửa sản phẩm':'Thêm sản phẩm',`<form id="product-form" data-id="${p?.id||''}">${field('name','Tên sản phẩm *','text',p?.name||'','required maxlength="150"')}<div class="form-grid"><div class="field"><label for="category">Danh mục *</label><select id="category" name="category">${categories.map(c=>`<option ${p?.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div>${field('price','Giá gốc (đ) *','number',p?.price||'','required min="1" step="1"')}${field('sku','SKU duy nhất *','text',p?.sku||'','required maxlength="30"')}<div class="field"><label for="active">Trạng thái</label><select id="active" name="active"><option value="1">Đang kinh doanh</option><option value="0" ${p?.active===false?'selected':''}>Ngừng kinh doanh</option></select></div></div><div class="field"><label><input type="checkbox" name="hot" ${p?.hot?'checked':''}> Hiển thị trong Sản phẩm hot</label></div><div class="field"><label for="image">Ảnh sản phẩm (JPG/PNG, tối đa 2 MB)</label><input id="image" type="file" accept="image/jpeg,image/png" name="image"></div><div class="form-grid">${field('sizes','Kích thước *','text',p?.sizes?.join(', ')||'S, M, L, XL','required maxlength="150"')}${field('colors','Màu sắc *','text',p?.colors?.join(', ')||'Kem, Đen','required maxlength="200"')}</div><p class="notice">Nhập các kích thước và màu sắc, ngăn cách bằng dấu phẩy. Mỗi sản phẩm có một mức giá chung.</p><div class="gap"></div><button class="btn full">Lưu sản phẩm mẫu</button></form>`)}if(a==='category'){const c=b.hasAttribute('data-index')?categories[i]:'';modal(c?'Đổi tên danh mục':'Thêm danh mục',`<form id="category-form" data-index="${c?i:-1}">${field('name','Tên danh mục *','text',c,'required maxlength="100"')}<button class="btn full">Lưu danh mục</button></form>`)}if(a==='lock'){let people=read('people',[]),target=people[i];if(!target)return;modal(target.locked?'Mở khóa hồ sơ thử':'Khóa hồ sơ thử',`<p>${esc(target.email)}</p><button class="btn full" data-action="confirm-lock" data-index="${i}">Xác nhận</button>`)}if(a==='confirm-lock'){let people=read('people',[]),target=people[i];target.locked=!target.locked;write('people',people);if(user?.email===target.email&&target.locked){user=null;write('user',null);cart=[];saveCart()}$('#modal').close();render();toast('Đã cập nhật hồ sơ thử.')}});
document.addEventListener('change',e=>{if(e.target.id==='sort'){const {params}=route();params.set('sort',e.target.value);go('products?'+params)}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.matches('form'))return;e.preventDefault();const d=Object.fromEntries(new FormData(f));if(f.id==='filter-form'){if(d.min&&d.max&&Number(d.min)>Number(d.max))return toast('Giá thấp nhất không được lớn hơn giá cao nhất.');go('products?'+new URLSearchParams(d))}if(f.id==='admin-filter')go('admin/'+route().path[1]+'?'+new URLSearchParams(d));if(f.id==='auth-form'){if(d.confirm&&d.confirm!==d.password)return toast('Mật khẩu xác nhận chưa khớp.');let people=read('people',[]),email=d.email.trim().toLowerCase(),old=people.find(u=>u.email===email);if(old?.locked)return toast('Hồ sơ thử này đang bị khóa.');if(f.dataset.mode==='register'&&old)return toast('Email đã có trong hồ sơ thử.');if(user?.email!==email){if(user)write('cart.'+user.email,cart);cart=read('cart.'+email,[]);write('cart',cart)}user={email,name:d.name?.trim()||old?.name||'Bạn '+email.split('@')[0],phone:d.phone||old?.phone||'',address:old?.address||''};write('user',user);if(!old)people.push(user);write('people',people);const next=read('returnTo',null)||f.dataset.next;write('returnTo',null);go(next||'account');toast('Đã mở hồ sơ thử.')}if(f.id==='account-form'){user={...user,...d,name:d.name.trim()};write('user',user);let people=read('people',[]);people=people.map(p=>p.email===user.email?{...p,...user}:p);write('people',people);toast('Đã lưu thông tin.')}if(f.id==='checkout-form'){if(!user||!cart.length)return toast('Vui lòng kiểm tra lại giỏ hàng.');let valid=cart.every(c=>{const p=product(c.id);return p&&p.active!==false&&available(p,c.size,c.color)>=c.qty});if(!valid)return toast('Một sản phẩm hoặc lựa chọn không còn khả dụng. Hãy cập nhật giỏ.');const id='BEE'+Date.now().toString().slice(-9),o={id,email:user.email,name:d.name.trim(),phone:d.phone,address:[d.address,d.ward,d.district,d.city].map(x=>x.trim()).join(', '),note:d.note,date:new Date().toISOString(),status:'Chờ xác nhận',total:total(),items:cart.map(c=>({...product(c.id),...c,price:finalPrice(product(c.id))}))};orders.unshift(o);saveOrders();saveProducts();cart=[];saveCart();go('success/'+id)}if(f.id==='cancel-form'){const o=orders.find(o=>o.id===f.dataset.id),admin=route().path[0]==='admin';if(!d.reason.trim())return toast('Nhập lý do hủy.');if(!o||!(o.status==='Chờ xác nhận'||admin&&o.status==='Đã xác nhận'))return toast('Đơn không còn được phép hủy.');if(!admin){o.cancelRequest=d.reason.trim();saveOrders();$('#modal').close();render();toast('Đã gửi yêu cầu hủy, chờ Admin xử lý.');return;}o.cancelRequest=null;o.status='Đã hủy';o.reason=d.reason.trim();saveOrders();saveProducts();$('#modal').close();render();toast('Đã hủy đơn hàng thử.')}if(f.id==='product-form'){let p=product(f.dataset.id),file=$('[name=image]',f).files[0],image=p?.image;if(!d.name.trim())return toast('Vui lòng nhập tên sản phẩm.');if(file){if(!['image/jpeg','image/png'].includes(file.type)||file.size>2*1024*1024)return toast('Ảnh phải là JPG/PNG và không quá 2 MB.');image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}const sizes=[...new Set(d.sizes.split(',').map(x=>x.trim()).filter(Boolean))],productColors=[...new Set(d.colors.split(',').map(x=>x.trim()).filter(Boolean))];if(!sizes.length||!productColors.length||!Number.isFinite(Number(d.price))||Number(d.price)<=0||!d.sku.trim()||!categories.includes(d.category))return toast('Kiểm tra kích thước, màu sắc, giá, mã và danh mục sản phẩm.');let v={sizes,colors:productColors,hot:d.hot==='on',tag:d.hot==='on'?'HOT':(p?.tag==='HOT'?'':p?.tag||''),name:d.name.trim(),category:d.category,price:Number(d.price),sku:d.sku.trim(),active:d.active==='1',image};if(products.some(x=>x.id!==p?.id&&x.sku.toLowerCase()===v.sku.toLowerCase()))return toast('SKU đã tồn tại.');if(p)Object.assign(p,v);else {p={...BEE_DATA.products[0],id:Math.max(0,...products.map(p=>p.id))+1,...v,tag:'NEW ARRIVAL'};prepareProduct(p);products.push(p);}saveProducts();$('#modal').close();render();toast('Đã lưu sản phẩm mẫu.')}if(f.id==='category-form'){let name=d.name.trim(),i=Number(f.dataset.index);if(!name)return toast('Nhập tên danh mục.');if(categories.some((c,j)=>j!==i&&c.toLowerCase()===name.toLowerCase()))return toast('Tên danh mục đã tồn tại.');if(i>=0){let old=categories[i];categories[i]=name;products.forEach(p=>{if(p.category===old)p.category=name});saveProducts()}else categories.push(name);write('categories',categories);$('#modal').close();render();toast('Đã lưu danh mục.')}});
function salePage(params){params.set('sale','1');return catalog(params)}
function wishPage(){if(!user)return auth('login','wishlist');const ids=read('wish.'+user.email,[]),list=products.filter(p=>ids.includes(p.id)&&p.active!==false);return `${crumb('Sản phẩm yêu thích')}<main class="wrap section"><div class="page-heading"><h1>Những món đồ bạn thích.</h1><p>Lưu lại để dễ tìm vào lần ghé thăm sau.</p></div>${list.length?'<div class="product-grid">'+list.map(card).join('')+'</div>':empty('Chưa có sản phẩm yêu thích','Bấm trái tim trên sản phẩm để lưu vào danh sách.')}</main>`}
function reviewPanel(p){const list=reviews.filter(r=>r.productId===p.id&&r.status==='approved'),eligible=user&&orders.some(o=>o.email===user.email&&o.status==='Hoàn thành'&&o.items.some(c=>c.id===p.id)),own=user&&reviews.find(r=>r.productId===p.id&&r.email===user.email);return `<section class="section"><div class="section-top"><div><div class="eyebrow">Đánh giá sản phẩm</div><h2>Trải nghiệm của khách hàng.</h2></div><span>${list.length} đánh giá đã duyệt</span></div>${list.map(r=>`<article class="panel review"><b>${esc(r.name)}</b><span class="stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span><p>${esc(r.content)}</p></article>`).join('')||'<p class="muted">Sản phẩm chưa có đánh giá được duyệt.</p>'}${own?`<p class="notice">Đánh giá của bạn: ${own.status==='pending'?'Đang chờ kiểm duyệt':own.status==='approved'?'Đã được duyệt':'Không được duyệt'}.</p>`:eligible?`<form id="review-form" data-id="${p.id}" class="panel"><h3>Viết đánh giá của bạn</h3><div class="field"><label for="rating">Số sao</label><select name="rating" id="rating">${[5,4,3,2,1].map(i=>`<option value="${i}">${i} sao</option>`).join('')}</select></div><div class="field"><label for="content">Nội dung *</label><textarea name="content" id="content" required maxlength="1000" rows="3"></textarea></div><button class="btn">Gửi đánh giá</button></form>`:'<p class="notice">Đăng nhập và hoàn thành đơn mua sản phẩm này để gửi đánh giá. Đánh giá sẽ hiển thị sau khi Admin duyệt.</p>'}</section>`}
function extraAdmin(section){if(section==='promotions')return `<div class="admin-title"><div><h1>Chương trình khuyến mãi</h1><p>A04 · Giảm theo phần trăm, sản phẩm áp dụng và thời gian.</p></div><button class="btn" data-action="promo">+ Thêm chương trình</button></div><div class="panel table-wrap"><table><thead><tr><th>Tên chương trình</th><th>Mức giảm</th><th>Hiệu lực</th><th>Áp dụng</th><th></th></tr></thead><tbody>${promotions.map(p=>`<tr><td>${esc(p.name)}<small>${p.active?'Đang bật':'Đang tắt'}</small></td><td>${p.percent}%</td><td>${esc(p.start)} → ${esc(p.end)}</td><td>${p.ids.length} sản phẩm</td><td><button class="text-link" data-action="promo" data-id="${p.id}">Chỉnh sửa</button></td></tr>`).join('')}</tbody></table></div>`;return `<div class="admin-title"><div><h1>Kiểm duyệt đánh giá</h1><p>A05 · Đánh giá chỉ xuất hiện khi được duyệt.</p></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Sản phẩm / Người gửi</th><th>Nội dung</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>${reviews.length?reviews.map(r=>`<tr><td>${esc(product(r.productId)?.name)}<small>${esc(r.name)}</small></td><td style="white-space:normal;min-width:200px">${'★'.repeat(r.rating)}<br>${esc(r.content)}</td><td>${{pending:'Chờ duyệt',approved:'Đã duyệt',rejected:'Từ chối'}[r.status]}</td><td>${r.status==='pending'?`<button class="text-link" data-action="moderate" data-id="${r.id}" data-value="approved">Duyệt</button> / <button class="text-link" data-action="moderate" data-id="${r.id}" data-value="rejected">Từ chối</button>`:'Đã xử lý'}</td></tr>`).join(''):'<tr><td colspan="4">Chưa có đánh giá cần kiểm duyệt.</td></tr>'}</tbody></table></div>`}
function statistics(params){const now=new Date(),end=params.get('end')||now.toLocaleDateString('en-CA'),start=params.get('start')||end.slice(0,7)+'-01';const within=date=>{const day=new Date(date).toLocaleDateString('en-CA');return day>=start&&day<=end};const placed=orders.filter(o=>within(o.date)),done=orders.filter(o=>o.status==='Hoàn thành'&&o.completedAt&&within(o.completedAt)),sold={};for(const o of done)for(const c of o.items){if(!sold[c.id])sold[c.id]={id:c.id,name:c.name,qty:0,value:0};sold[c.id].qty+=c.qty;sold[c.id].value+=c.price*c.qty}const top=Object.values(sold).sort((a,b)=>b.qty-a.qty||a.id-b.id).slice(0,5),revenue=done.reduce((n,o)=>n+orderTotal(o),0);return `<div class="admin-title"><div><div class="eyebrow">A08 / Báo cáo cửa hàng</div><h1>Thống kê doanh thu.</h1><p>Doanh thu từ các đơn hàng cửa hàng đã hoàn thành.</p></div></div><form id="stats-form" class="panel admin-table-tools">${field('start','Từ ngày','date',start,'required')}${field('end','Đến ngày','date',end,'required')}<button class="btn" style="align-self:end;margin-bottom:17px">Xem thống kê</button></form><div class="stats">${[['Doanh thu hàng hóa',money(revenue),'Theo ngày hoàn thành'],['Đơn hoàn thành',done.length,'Theo ngày hoàn thành'],['Đơn đã đặt',placed.length,'Theo ngày đặt'],['Chờ xác nhận',placed.filter(o=>o.status==='Chờ xác nhận').length,'Theo ngày đặt']].map(([t,v,n])=>`<div class="stat"><p>${t}</p><strong>${v}</strong><small>${n}</small></div>`).join('')}</div><section class="panel"><h3>Top 5 sản phẩm bán chạy</h3><p class="muted">Tổng số lượng ở các đơn Hoàn thành trong khoảng ngày đã chọn.</p><div class="table-wrap"><table><thead><tr><th>Hạng</th><th>Sản phẩm</th><th>Đã bán</th><th>Doanh thu</th></tr></thead><tbody>${top.length?top.map((p,i)=>`<tr><td>${i+1}</td><td>${esc(p.name)}</td><td>${p.qty}</td><td>${money(p.value)}</td></tr>`).join(''):'<tr><td colspan="4">Chưa có đơn hoàn thành trong khoảng ngày này.</td></tr>'}</tbody></table></div></section>`}
function updateProductChoice(){const p=product(route().path[1]);if(!p)return;selected.qty=1;$('#detail-qty').textContent=1;const n=available(p,selected.size,selected.color);$('#product-availability').textContent=n?'● Sản phẩm đang kinh doanh':'○ Lựa chọn không khả dụng';$('[data-action=add-cart]').disabled=!n}
function setupBeeEvents(){document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=Number(b.dataset.id),p=product(id);if(a==='size'||a==='color')updateProductChoice();if(a==='wish'){if(!user){write('returnTo','wishlist');toast('Đăng nhập để lưu sản phẩm yêu thích.');go('login');return}let ids=read('wish.'+user.email,[]);ids=ids.includes(id)?ids.filter(x=>x!==id):[...ids,id];write('wish.'+user.email,ids);const y=scrollY;render();scrollTo(0,y);toast(ids.includes(id)?'Đã lưu sản phẩm yêu thích.':'Đã bỏ khỏi yêu thích.')}if(a==='moderate'){const r=reviews.find(x=>x.id===id);if(r?.status!=='pending')return;r.status=b.dataset.value;write('reviews',reviews);render();toast('Đã xử lý đánh giá.')}if(a==='promo'){const promo=promotions.find(x=>x.id===id);modal(promo?'Chỉnh sửa khuyến mãi':'Thêm khuyến mãi',`<form id="promo-form" data-id="${promo?.id||''}">${field('name','Tên chương trình *','text',promo?.name||'','required maxlength="120"')}${field('percent','Mức giảm (%) *','number',promo?.percent||10,'required min="1" max="90" step="1"')}<div class="form-grid">${field('start','Ngày bắt đầu *','date',promo?.start||'','required')}${field('end','Ngày kết thúc *','date',promo?.end||'','required')}</div><div class="field"><label>Sản phẩm áp dụng *</label><div class="promo-products">${products.map(p=>`<label><input type="checkbox" name="ids" value="${p.id}" ${promo?.ids.includes(p.id)?'checked':''}> ${esc(p.name)}</label>`).join('')}</div></div><div class="field"><label><input name="active" type="checkbox" ${!promo||promo.active?'checked':''}> Bật chương trình</label></div><p class="notice">Nếu trùng chương trình, áp dụng mức giảm cao nhất. Không cộng dồn.</p><button class="btn full">Lưu chương trình</button></form>`)}if(a==='password'){modal('Đổi mật khẩu',`<form id="password-form">${field('current','Mật khẩu hiện tại *','password','','required minlength="8"')}${field('password','Mật khẩu mới *','password','','required minlength="8"')}${field('confirm','Nhập lại mật khẩu mới *','password','','required minlength="8"')}<p class="notice">Bản giao diện chỉ kiểm tra độ dài và xác nhận khớp; chưa xác thực hoặc lưu mật khẩu.</p><button class="btn full">Kiểm tra thay đổi</button></form>`)}if(a==='approve-cancel'||a==='reject-cancel'){const o=orders.find(o=>o.id===b.dataset.id);if(!o?.cancelRequest||o.status!=='Chờ xác nhận')return toast('Yêu cầu không còn hợp lệ.');if(a==='approve-cancel'){o.status='Đã hủy';o.reason=o.cancelRequest;saveProducts()}else o.cancelRejection='Cửa hàng không chấp nhận yêu cầu hủy.';o.cancelRequest=null;saveOrders();render();toast('Đã xử lý yêu cầu hủy.')}});
document.addEventListener('submit',e=>{const f=e.target,d=Object.fromEntries(new FormData(f));if(f.id==='review-form'){const id=Number(f.dataset.id),p=product(id);if(!user||!orders.some(o=>o.email===user.email&&o.status==='Hoàn thành'&&o.items.some(c=>c.id===id)))return toast('Chỉ đánh giá sản phẩm đã mua thành công.');if(reviews.some(r=>r.email===user.email&&r.productId===id))return toast('Bạn đã gửi đánh giá cho sản phẩm này.');if(!d.content.trim())return toast('Nhập nội dung đánh giá.');reviews.unshift({id:Date.now(),productId:p.id,email:user.email,name:user.name,rating:Number(d.rating),content:d.content.trim(),status:'pending'});write('reviews',reviews);render();toast('Đánh giá đã gửi để kiểm duyệt.')}if(f.id==='promo-form'){const id=Number(f.dataset.id),ids=new FormData(f).getAll('ids').map(Number);if(!d.name.trim()||!ids.length||d.start>d.end||Number(d.percent)<1||Number(d.percent)>90)return toast('Kiểm tra tên, mức giảm, thời gian và sản phẩm áp dụng.');const v={id:id||Date.now(),name:d.name.trim(),percent:Number(d.percent),ids,start:d.start,end:d.end,active:!!d.active};const old=promotions.findIndex(x=>x.id===id);if(old>=0)promotions[old]=v;else promotions.push(v);write('promotions',promotions);$('#modal').close();render();toast('Đã lưu chương trình.')}if(f.id==='stats-form'){if(d.start>d.end)return toast('Ngày bắt đầu không được sau ngày kết thúc.');go('admin/dashboard?'+new URLSearchParams(d))}if(f.id==='password-form'){if(d.password!==d.confirm)return toast('Mật khẩu xác nhận chưa khớp.');$('#modal').close();toast('Biểu mẫu hợp lệ. Chức năng lưu mật khẩu cần máy chủ.')}})}

setupBeeEvents();
window.addEventListener('hashchange',()=>{if($('#modal').open)$('#modal').close();render();scrollTo(0,0)});render();
})();
